package model

import "github.com/fakeyanss/jt808-server-go/internal/codec/hex"

// Msg0805 returns the result and IDs generated by a camera command.
type Msg0805 struct {
	Header       *MsgHeader `json:"header"`
	AnswerSerial uint16     `json:"answerSerial"`
	Result       uint8      `json:"result"`
	MediaIDs     []uint32   `json:"mediaIds,omitempty"`
}

func (m *Msg0805) Decode(p *PacketData) error {
	if p == nil || p.Header == nil || len(p.Body) < 3 {
		return ErrDecodeMsg
	}
	m.Header = p.Header
	i := 0
	m.AnswerSerial = hex.ReadWord(p.Body, &i)
	m.Result = hex.ReadByte(p.Body, &i)
	if m.Result != 0 {
		if i != len(p.Body) {
			return ErrDecodeMsg
		}
		return nil
	}
	if len(p.Body) < 5 {
		return ErrDecodeMsg
	}
	count := int(hex.ReadWord(p.Body, &i))
	if len(p.Body) != i+count*4 {
		return ErrDecodeMsg
	}
	m.MediaIDs = make([]uint32, 0, count)
	for n := 0; n < count; n++ {
		m.MediaIDs = append(m.MediaIDs, hex.ReadDoubleWord(p.Body, &i))
	}
	return nil
}
func (m *Msg0805) Encode() ([]byte, error) {
	if m.Header == nil {
		return nil, ErrEncodeMsg
	}
	b := hex.WriteWord(nil, m.AnswerSerial)
	b = append(b, m.Result)
	if m.Result == 0 {
		if len(m.MediaIDs) > 65535 {
			return nil, ErrEncodeMsg
		}
		b = hex.WriteWord(b, uint16(len(m.MediaIDs)))
		for _, id := range m.MediaIDs {
			b = hex.WriteDoubleWord(b, id)
		}
	}
	return writeHeader(m, b)
}
func (m *Msg0805) GetHeader() *MsgHeader { return m.Header }
func (m *Msg0805) GenOutgoing(incoming JT808Msg) error {
	cmd, ok := incoming.(*Msg8801)
	if !ok {
		return ErrGenOutgoingMsg
	}
	m.Header = cloneReplyHeader(cmd.Header, 0x0805)
	m.AnswerSerial = cmd.Header.SerialNumber
	m.Result = 0
	m.MediaIDs = []uint32{uint32(cmd.Header.SerialNumber) + 1}
	return nil
}
